// Marked.js fallback placeholder - official library is downloaded during GitHub Actions build
(function (global) {
    if (typeof global.marked === 'undefined') {
        global.marked = {
            parse: function (markdownString) {
                if (!markdownString) return "";
                var html = String(markdownString)
                    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
                    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
                    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
                    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
                    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
                    .replace(/`([^`]+)`/gim, '<code>$1</code>')
                    .replace(/\[([^\]]+)\]\(([^)]+)\)/gim, '<a href="$2">$1</a>')
                    .replace(/\n\n+/g, '</p><p>')
                    .replace(/\n/g, '<br>');
                return '<p>' + html + '</p>';
            }
        };
    }
})(typeof window !== 'undefined' ? window : this);
